// MT2009_PLUS_DIGI_FIXES_V1 (safebox grid): Autor: Digi Rasta. m_pkGrid was asked after
// the std::move above, so it was always empty and the new grid never knew the occupied
// cells of an open safebox that grew (CGrid's copy also left the new rows unset): an
// item could be put over another. The grid is rebuilt from the items.
m_pkGrid = std::make_unique<CGrid>(SAFEBOX_PAGE_WIDTH, m_iSize * SAFEBOX_PAGE_HEIGHT);
for (int i = 0; i < SAFEBOX_MAX_NUM; ++i)
	if (m_pkItems[i])
		m_pkGrid->Put(i, 1, m_pkItems[i]->GetSize());

if (false == Cube_load(file_name))
	sys_err("Cube_Init failed");

// MT2009_PLUS_DIGI_FIXES_V1 (cube reload): Autor: Digi Rasta. /reload c read the recipes
// again, but the window's recipe lists (cube_info_map) were built once - the window kept
// showing the old ones. On a reload they are built again, every open cube window is
// closed and the client forgets its lists ("CubeReload", game.py).
if (s_isInitializedCubeMaterialInformation)
{
	cube_info_map.clear();
	cube_result_info_map_by_npc.clear();
